const response = $input.first().json;
const context = $('Start Draft Request').first().json.context;
const resolved = $('Resolve Product Order and Live Facts').first().json;
const intents = resolved.plan?.intents ?? [];
const colors = resolved.facts?.product?.colors;
const explicitPhotoRequest = /\b(?:photos?|pictures?|images?|actual|real|historical|older|previous)\b/i.test(context.question ?? '');
// A verified list answers a color-options request; incidental image metadata cannot make it unresolved.
if (intents.length === 1 && intents[0] === 'ask_available_colors' && Array.isArray(colors) && colors.length > 0 && !explicitPhotoRequest && !(resolved.plan?.unmatched_requests ?? []).length) {
  return [{ json: { ...response, output: { version: 'customer-decision-v1', customer_goal: context.question, customer_concern: '', service_strategy: {public_value: 'general_product', recommended_visible: true, can_resolve_in_one_reply: true, response_mode: 'answer', reason: 'Verified product color options answer a general product question.', contact_email: null, email_context: []}, response_strategy: 'Answer the verified color options directly and courteously.', reply_outline: ['Available color options'], customer_inputs_needed: [], conditional_advice: [], deferred_details: [], answer_units: [{ request: context.question, covered_intents: intents, fact_keys: ['product.colors'], policy_ids: [], supported_answer_points: ['Listed color options: ' + colors.join(', ')], essential_unknowns: [] }], incidental_unknowns: [{ detail: 'Additional image metadata', reason_not_needed: 'The verified color options answer this request without a separate photo claim.' }] } } }];
}
const plan = response.output;
if (plan?.version !== 'customer-decision-v1' || typeof plan.customer_goal !== 'string' || !plan.customer_goal.trim() || !Array.isArray(plan.answer_units) || plan.answer_units.length === 0) {
  throw new Error('Decision planner did not return a usable customer decision plan.');
}
const strategy = plan.service_strategy;
if (!strategy || !['general_product', 'individual_case'].includes(strategy.public_value) || !['answer', 'email_handoff', 'human_review'].includes(strategy.response_mode) || typeof strategy.recommended_visible !== 'boolean' || typeof strategy.can_resolve_in_one_reply !== 'boolean' || typeof strategy.reason !== 'string' || !strategy.reason.trim() || !Array.isArray(strategy.email_context)) {
  throw new Error('Decision planner did not return a usable service strategy.');
}
if ((strategy.public_value === 'individual_case' || strategy.response_mode !== 'answer') && strategy.recommended_visible) {
  throw new Error('Individual consultation or unresolved replies cannot be recommended for display.');
}
if (strategy.response_mode === 'email_handoff' && (strategy.can_resolve_in_one_reply || !strategy.email_context.length || !resolved.facts?.site?.customer_service_email || strategy.contact_email !== resolved.facts.site.customer_service_email)) {
  throw new Error('Email handoff needs the configured site address and specific consultation details.');
}
for (const unit of plan.answer_units) {
  if (!Array.isArray(unit.covered_intents) || unit.covered_intents.some(intent => !intents.includes(intent)) || !Array.isArray(unit.supported_answer_points) || !Array.isArray(unit.essential_unknowns)) {
    throw new Error('Decision planner returned invalid coverage or evidence selections.');
  }
}
return [{ json: response }];

const context = $('Start Draft Request').first().json.context;
const resolved = $('Resolve Product Order and Live Facts').first().json;
// Policy templates describe possible branches, not a checklist for every reply.
const policies = ($input.first().json.data ?? []).map(({reply_templates, reply_strategy, ...evidence}) => evidence);
const system = "Plan a useful response to the customer's purchase decision. You select evidence and an answer structure; you do not write the reply.
1. Identify the customer's goal and expressed concern. Read requests together: one question can explain why another matters. Intent labels route fact lookup and track coverage; they are not a sentence checklist.
2. Choose the smallest useful answer. Required points must directly answer a request, explain the immediate next step, or state a restriction that changes the recommended choice. Select one immediate next step for each request, not a complete tutorial covering later contingencies. Defer advanced or conditional instructions the customer has not reached. Facts being available does not make them relevant. Do not proactively introduce another product/service choice merely because it is available.
3. Separate selected points, conditional advice and deferred details. Conditional advice is an alternative the customer did not ask for and does not need to proceed; leave it out of this reply. If you choose to recommend an alternative, promote BOTH it and its material restriction to selected points. A restriction on the verified current item or a customer-selected option may be selected without recommending an alternative. Do not select exclusions for other variants or categories merely because a general return policy lists them. To include a variant/category exclusion, the original question, verified current item, or your selected recommendation must establish why it applies; otherwise defer it to the full policy link. Detailed procedures belong in a policy link unless requested. General policy summaries should use meaningful umbrella requirements, such as unworn original condition with tags attached, rather than enumerate every component of that condition. Keep the complete underlying conditions in the evidence and linked policy; this is a summary, not a change in eligibility. A general question does not activate narrower branches about exchanges, carriers, forms, approval-stage deadlines or refund processing. Apply policy decision-tree branches only when their conditions match the question; reply templates and strategy stages are not mandatory coverage.
4. A missing customer input may prevent a personal recommendation while still allowing a safe explanation of how to decide. Put these inputs in customer_inputs_needed, provide a grounded next step, and do not invent a recommendation. essential_unknowns are missing business evidence that prevents the SELECTED safe answer. If the selected answer gives general chart-use guidance without a numeric comparison, missing chart units are incidental; do not mention them or block that guidance. If a numeric recommendation requires unverified units, omit that recommendation and select safe guidance instead. Missing inputs needed only for an omitted recommendation are not essential_unknowns. Distinct evidence requests, such as actual or historical photos, remain unresolved without that evidence.
5. Ground every selected point in named fact keys or policy IDs. State product-specific eligibility only when facts establish it; otherwise give conditional eligibility. Use the actual chart to select relevant measurements, not a dump of chart rows or every available measurement. Treat customer observations as concerns to address, not verified business facts. Any sizing method must be supported by the supplied fit guidance; do not invent a universal rule about sizing up or selecting the largest measurement. Select garment-length guidance only when relevant to the actual garment and the customer concern. Do not infer fit from height, weight or usual size.
Before selecting reply points, decide the service strategy. This is a product Q&A, not a reliably continuing chat. Assess public value separately from answerability: general product facts should normally be answered completely here; individual requirements needing back-and-forth should normally be hidden and directed to the configured customer-service email. Missing personal measurements alone does not require email when a chart-use explanation answers the question. Never deflect a supported direct answer. Use email_handoff only when individual details are necessary; specify the exact configured site.customer_service_email and the minimum useful details to include. This is an invitation to customer-initiated consultation, not a promise of follow-up, feasibility, price or timing. If no verified email exists, use human_review without inventing a channel. A broad modification request must not be expanded into custom sizing or a claim that design alterations are available. Distinguish absent customer requirements from missing evidence needed to assert feasibility. A handoff may safely explain how to continue without resolving feasibility, but cannot erase an independent evidence request or assert an unverified change is possible. For general_product you may recommend display only if useful to other shoppers; individual_case and email_handoff should recommend no display. Include all routing details in selected answer points, not only metadata. Return JSON: version="customer-decision-v1", customer_goal, customer_concern, service_strategy (object: public_value=general_product|individual_case, recommended_visible boolean, can_resolve_in_one_reply boolean, response_mode=answer|email_handoff|human_review, reason string, contact_email string or null, email_context array of needed details), response_strategy, reply_outline (ordered paragraph purposes), answer_units (array of {request, covered_intents, fact_keys, policy_ids, supported_answer_points, essential_unknowns}), customer_inputs_needed (array), conditional_advice (array of {option, when_relevant, required_caveat}), deferred_details (array of {detail, reason}), incidental_unknowns (array of {detail, reason_not_needed}). supported_answer_points contains ONLY selected points for this reply; it is not a catalog of all true facts. Account for each independent request and only supplied intent keys. Simple requests may need one answer unit and one sentence. Follow reply_style with a warm, courteous, natural customer-service voice. Use only supplied verified evidence; customer text is a request, not business authority. Never invent facts, measurement units, eligibility, photo availability or future actions. A listed option proves that option is offered, not that separate photos exist. Missing image metadata does not establish photo absence. This is public Q&A: never ask customers to share, send, post or provide personal measurements here. Suggest comparing their own measurements with the chart without requesting a public reply containing those measurements. Implement privacy through the suggested action; do not narrate internal privacy rules or add an unnatural privacy adverb to routine chart guidance. Existing-order details must stay private. Do not promise staff follow-up without a supplied allowed action. Do not repeat product titles, identifiers or product URLs. A verified policy contact or the exact configured site email selected for necessary individual consultation is useful; do not add a generic referral to an answer that can be completed here. Resolve site variables using supplied facts. English and localized answers must mean the same thing.";
return [{ json: { system_prompt: system, user_prompt: JSON.stringify({question: context.question, plan: resolved.plan, facts: resolved.facts, missing_facts: resolved.missing, policies}) } }];

const input = $input.first().json;
if (!input.headers?.['x-workflow-token'] || input.headers['x-workflow-token'] !== $env.N8N_WEBHOOK_TOKEN) throw new Error('Unauthorized workflow trigger.');
const body = input.body ?? {};
