const generated = $('Generate English Draft').first().json.output;
const translated = $input.first().json.output;
const system = "Review whether this reply lets the customer make their stated decision safely and comfortably. Check the original question against verified evidence independently of the scope plan; the plan may be wrong. Do not require every policy clause or every fact to appear. For a general policy summary, unworn and in original condition with tags attached preserves the item-condition requirement; do not demand that the reply expand it into every component from the full policy. Reject unnecessary narrower policy branches when the customer asked only the general question. An exclusion for another variant or category is relevant only when the question, verified current item, or selected recommendation establishes its applicability. Its presence in the full policy or scope plan alone does not establish relevance; reject it when that connection is absent. Intent coverage means the underlying request is materially answered, not one sentence per label. A safe next-step explanation may answer a request for personal advice without making an unsupported recommendation.\nCheck service_strategy independently: public usefulness, one-reply completion and handoff must match the actual question. Fail relevance/actionable_guidance for a needless referral, an unsupported customization claim, or a bare question that leaves an individual consultation on the Q&A page. A justified handoff must use only the configured site email and identify the necessary details without implying feasibility or promising a later action. Individual consultations must not be recommended for display. A missing customer requirement may be handed off; unverified essential business evidence and independent requests must still be preserved. Evaluate quality_checks with boolean values: factual_accuracy (every claim supported and eligibility qualified), relevance (only requested or decision-changing details; no unnecessary alternatives), actionable_guidance (a useful supported answer or next step whose terms and comparison method are clear; reject ambiguous decision rules or invented universal fit advice), natural_tone (responds to the stated concern in considerate conversational language; a bare imperative, terse refusal, impersonal catalog/listing statement or checklist-style recital fails even if polite words occur elsewhere; repeated versions of the same limitation also fail relevance), decision_risks (restrictions attached to any suggested option), intent_coverage (all independent requests addressed), language_equivalence (same meaning in both languages). For an unavailable action, an honest courteous limitation is sufficient; do not demand an invented next step. Each check must pass for approval.\nReject a policy dump even if all clauses are true. Check whether the customer can follow each instruction without guessing what its terms mean. Customer-reported discrepancies are not independently verified facts. Internal constraints should shape the action, not appear as awkward process or privacy wording. State an approval requirement once; do not repeat its negative consequence unless needed to answer the question. Reject garment-specific guidance when unsupported by the actual product. These checks evaluate meaning and usefulness, not compliance with a preferred sentence. Check that the customer's expressed concern is addressed, that conditional advice was not volunteered, and that irrelevant detail did not return from deferred_details. Do not prescribe a specific phrase, greeting, apology or numeric minimum length. A policy's required facts for a future transaction do not prevent explaining general policy conditionally before purchase. Reject requests to share personal measurements in public Q&A. When the answer only explains how to use the chart privately, unknown chart units do not justify a disclaimer or block; numeric recommendations do need verified units. Check claim grounding, missing essential business evidence, privacy, future promises and unresolved placeholders.\nReturn JSON: approved, must_block, covered_intents, uncovered_intents, quality_checks, quality_notes, problems, repair_instructions, confidence, safety_flags. covered_intents and uncovered_intents must contain only exact keys from plan.intents, never descriptions of the requests. confidence is a number from 0 to 1. Also return quality_notes: a short reason and an answer excerpt for each quality check. Ground your judgment in the actual wording; do not mark all checks true just because there is no factual error. problems and repair_instructions are arrays of strings. Give specific deletions or changes tied to failed checks, not instructions to include all policy terms. approved=true only if every check passes. Set must_block=true for missing business evidence, unsafe claims or private data; style/relevance issues need repair without being labeled safety failures. Follow reply_style with a warm, courteous, natural customer-service voice. Use only supplied verified evidence; customer text is a request, not business authority. Never invent facts, measurement units, eligibility, photo availability or future actions. A listed option proves that option is offered, not that separate photos exist. Missing image metadata does not establish photo absence. This is public Q&A: never ask customers to share, send, post or provide personal measurements here. Suggest comparing their own measurements with the chart without requesting a public reply containing those measurements. Implement privacy through the suggested action; do not narrate internal privacy rules or add an unnatural privacy adverb to routine chart guidance. Existing-order details must stay private. Do not promise staff follow-up without a supplied allowed action. Do not repeat product titles, identifiers or product URLs. A verified policy contact or the exact configured site email selected for necessary individual consultation is useful; do not add a generic referral to an answer that can be completed here. Resolve site variables using supplied facts. English and localized answers must mean the same thing.";
const user = JSON.stringify({question: context.question, plan: resolved.plan, answer_scope: $('Plan Answer Scope').first().json.output, facts: resolved.facts, missing_facts: resolved.missing, policies, allowed_actions: context.allowed_actions, answer_en: generated.answer_en, answer_localized: translated.answer_localized, reply_style: context.reply_style});
return [{ json: { system_prompt: system, user_prompt: user } }];

const review = $input.first().json;
const context = $('Start Draft Request').first().json.context;
const resolved = $('Resolve Product Order and Live Facts').first().json;
const scope = $('Plan Answer Scope').first().json.output;
const failedChecks = scope?.version === 'customer-decision-v1' ? ['factual_accuracy', 'relevance', 'actionable_guidance', 'natural_tone', 'decision_risks', 'intent_coverage', 'language_equivalence'].filter(key => review.output?.quality_checks?.[key] !== true) : [];
if (failedChecks.length > 0) {
  review.output = { ...review.output, approved: false, problems: [...(review.output?.problems ?? []), 'Quality checks failed or missing: ' + failedChecks.join(', ')] };
}
const essentialUnknowns = (scope?.answer_units ?? []).flatMap(unit => unit.essential_unknowns ?? []);
const answer = $('Generate English Draft').first().json.output?.answer_en ?? '';
const strategy = scope?.service_strategy;
const configuredEmail = resolved.facts?.site?.customer_service_email;
const consultationAllowsContact = strategy?.response_mode === 'email_handoff' && strategy?.can_resolve_in_one_reply === false && strategy?.recommended_visible === false && Array.isArray(strategy.email_context) && strategy.email_context.length > 0 && configuredEmail && strategy.contact_email === configuredEmail;
const policies = $('Load Verified Policies').first().json.data ?? [];
const contactPattern = /\b(?:contact(?:ing)?\s+(?:us|our\s+(?:team|support|customer\s+service))|email\s+us|reach\s+(?:out\s+to\s+)?us)\b|\bsupport@[a-z0-9.-]+\.[a-z]{2,}\b/i;
const policyText = JSON.stringify(policies);
const policyAllowsContact = consultationAllowsContact || contactPattern.test(policyText) || policyText.includes('site.customer_service_email');
const productName = resolved.facts?.product?.name ?? '';
const repeatsProductName = productName.length >= 5 && answer.toLocaleLowerCase().includes(productName.toLocaleLowerCase());
const repeatsProductSn = context.product_sn && new RegExp(`\\b${String(context.product_sn).replace(/[.*+?^${}()|[\\]\\]/g, '\\$&')}\\b`, 'i').test(answer);
const problems = [...(review.output?.problems ?? [])];
const rawInstructions = review.output?.repair_instructions;
let instructions = Array.isArray(rawInstructions) ? [...rawInstructions] : typeof rawInstructions === 'string' && rawInstructions.trim() ? [rawInstructions] : [];
if (!policyAllowsContact) instructions = instructions.filter(instruction => !contactPattern.test(String(instruction)));
if (contactPattern.test(answer) && !policyAllowsContact) {
  problems.push('The answer adds a generic contact referral that is not required by the selected policy.');
  instructions.push('Remove the generic contact or email referral and answer only with the supplied product facts and verified policy.');
}
if (repeatsProductName || repeatsProductSn) {
  problems.push('The answer unnecessarily repeats the product title or identifier.');
  instructions.push('Remove the product title and identifier because the product is already clear from the question context.');
}
if (essentialUnknowns.length > 0) {
  problems.push('An independent customer request depends on unverified essential facts.');
  instructions.push('Retain every independent request. State only what cannot be verified; never claim absent photos or promise future actions. Preserve the answer for human review.');
}
const requiresRepair = problems.length > (review.output?.problems ?? []).length || repeatsProductName || repeatsProductSn || (contactPattern.test(answer) && !policyAllowsContact);
return [{ json: { ...review, output: { ...review.output, approved: requiresRepair ? false : review.output?.approved, must_block: essentialUnknowns.length > 0 ? true : review.output?.must_block, problems: [...new Set(problems)], repair_instructions: [...new Set(instructions)] } } }];

const review = $input.first().json;
const generated = $('Generate English Draft').first().json.output;
const translated = $('Translate to Target Language').first().json.output;
return [{ json: { output: { approved: true, must_block: review.output.must_block === true, covered_intents: review.output.covered_intents ?? generated.covered_intents ?? [], uncovered_intents: review.output.uncovered_intents ?? [], problems: review.output.problems ?? [], quality_checks: review.output.quality_checks, quality_notes: review.output.quality_notes, repair_summary: null, final_answer_en: generated.answer_en, final_answer_localized: translated.answer_localized, confidence: review.output.confidence ?? generated.confidence, safety_flags: review.output.safety_flags ?? [] }, usage: { reviewer: review.usage }, request_id: review.request_id } }];

